import sys
sys.path.insert(0, '/workspace/tests')
from oracle import check_image_semantics
from harness import summary, FAILURES

SVC = [{"name": "A", "label": 10}, {"name": "B", "label": 4}, {"name": "C", "label": 7}]

cases = [
    ("match AB", "match(A,B) allow;"),
    ("match empty", "match() allow;"),
    ("startswith A", "startswith(A) allow;"),
    ("endswith B", "endswith(B) allow;"),
    ("contains AB", "contains(A,B) allow;"),
    ("contains empty", "contains() allow;"),
    ("startswith empty", "startswith() allow;"),
    ("endswith empty", "endswith() allow;"),
    ("or/and/not", "((match(A) or match(B)) and not(match(B))) allow;"),
    ("nested not", "not(not(match(A))) allow;"),
    ("mixed", "match(A,B) allow; match(B,A) allow; (contains(A) and endswith(B)) drop;"),
    ("complex drop", "contains() allow; (match(A) or match(B)) drop;"),
    ("drop startswith", "contains() allow; startswith(A,B) drop;"),
    ("union many", "".join(f"match({','.join(w)}) allow;" for w in
        ["A","B","C","A,A","A,B","B,A","B,B","C,C","A,B,C","B,C,A","C,A,B","A,C,B"])),
    ("nonmatch4", "(contains(A,B,C,A) or (endswith(C,A) and not(startswith(B,C,A,B)))) drop; contains() allow;"),
    ("kmp overlap", "contains(A,A,B) allow;"),
    ("kmp overlap2", "endswith(A,B,A,B) allow;"),
    ("complex32", "(contains() and not(" + " or ".join(f"match({','.join(['A','B','C'][i%3] for i in range(4))})" for _ in range(0)) + "match(A))) allow;"),
    ("epsilon drop", "contains() allow; match() drop;"),
    ("word and complex", "match(A,B,C) allow; (startswith(A) and endswith(C)) allow; contains(B,B) drop;"),
]

for name, pol in cases:
    ok = check_image_semantics(name, pol, SVC, None, max_len=5)
    if not ok:
        FAILURES.append(name)
summary()
